      "check_id": "CKV_AWS_290",
      "title": "Ensure IAM policies does not allow write access without constraints",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The policy allows 'sagemaker:CreatePresignedNotebookInstanceUrl' on all resources without constraints."
    },
    {
      "check_id": "CKV_AWS_355",
      "title": "Ensure no IAM policies documents allow '*' as a statement's resource for restrictable actions",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The policy allows 'sagemaker:CreatePresignedNotebookInstanceUrl' and 'sagemaker:ListNotebookInstances' on all resources."
    }
  ],
  "patched_code": "resource \"aws_iam_policy\" \"privesc-sageMakerCreatePresignedNotebookURL-policy\" {\n  name        = \"privesc-sageMakerCreatePresignedNotebookURL-policy\"\n  path        = \"/\"\n  description = \"Allows privesc via sagemakerCreatePresignedNotebookURL\"\n  policy = jsonencode({\n    Version = \"2012-10-17\"\n    Statement = [\n      {\n        Effect   = \"Allow\"\n        Action = \"sagemaker:ListNotebookInstances\"\n        Resource = \"*\"\n      },\n      {\n        Effect   = \"Allow\"\n        Action = \"sagemaker:CreatePresignedNotebookInstanceUrl\"\n        Resource = \"arn:aws:sagemaker:*:*:notebook-instance/*\"\n      },\n    ]\n  })\n}",
  "fix_summary": "Restricted 'sagemaker:CreatePresignedNotebookInstanceUrl' to notebook instances and kept 'sagemaker:ListNotebookInstances' on all resources."
}
